#include "stdlib/stats/base/dists/normal/median.h"
#include "stdlib/math/base/assert/is_nan.h"

/**
* Returns the differential entropy for a normal distribution with mean `mu` and standard deviation `sigma`.
*
* @param mu     mean of the distribution
* @param sigma  standard deviation of the distribution
* @return       median of the normal distribution
*
* @example
* double y = stdlib_base_normal_median( 0.0, 1.0 );
* // returns 0.0
*
* @example
* double y = stdlib_base_normal_median( 5.0, 2.0 );
* // returns 5.0
*
* @example
* double y = stdlib_base_normal_median( NAN, 1.0 );
* // returns NaN
*
* @example
* double y = stdlib_base_normal_median( 0.0, NAN );
* // returns NaN
*
* @example
* double y = stdlib_base_normal_median( 0.0, 0.0 );
* // returns NaN
*/
double stdlib_base_dists_normal_median( const double mu, const double sigma ) {
	if (
		stdlib_base_is_nan( mu ) ||
		stdlib_base_is_nan( sigma ) ||
		sigma <= 0.0
	) {
		return 0.0/0.0; // NaN
	}
	return mu;
}
